93	/* ---------- 问卷表单（新建 / 编辑共用） ---------- */
94	
95	function buildSurveyForm(existing, hooks, view) {
96	  const mode = existing ? "edit" : "create";
97	
98	  const banner = h("div", {class: "banner", id: "form-banner"});
99	  banner.hidden = true;
100	
101	  const titleInput = h("textarea", {id: "survey-title", rows: "1", class: "grow",
102	    placeholder: "请输入问卷标题（可含换行）"});
103	  const titleErr = h("p", {class: "field-err", id: "title-err"});
104	  const descArea = h("textarea", {id: "survey-desc", rows: "4", placeholder: "问卷说明（可留空，支持中文、引号与换行）"});
105	  const qBox = h("div", {id: "questions"});
106	  const qErr = h("p", {class: "field-err", id: "questions-err"});
107	
108	  function renumber() {
109	    const cards = qBox.querySelectorAll(".q-card");
110	    cards.forEach((card, i) => {
111	      card.querySelector(".q-index").textContent = `第 ${i + 1} 题`;
112	      card.querySelectorAll(".opt-row").forEach((row, j) => {
113	        row.querySelector(".opt-index").textContent = `选项 ${j + 1}`;
114	      });
115	    });
116	  }
117	
118	  // textarea 的高度随内容变化：单行内容外观与原输入框一致，出现内部换行时
119	  // 自动增高，让换行真实可见、可编辑，而不是被折叠或截断。
120	  function autoGrow(el) {
121	    el.style.height = "auto";
122	    el.style.height = `${el.scrollHeight}px`;
123	  }
124	  // 预填值时元素可能还没挂到文档上（scrollHeight 为 0），延到下一帧布局后再量。
125	  function scheduleGrow(el) { requestAnimationFrame(() => autoGrow(el)); }
126	
127	  function optionRow(value) {
128	    const text = h("textarea", {rows: "1", class: "opt-text grow", placeholder: "选项内容（可含换行）"});
129	    text.addEventListener("input", () => autoGrow(text));
130	    if (value !== undefined && value !== null) { text.value = value; scheduleGrow(text); }
131	    const row = h("div", {class: "opt-row"},
132	      h("span", {class: "opt-index"}, "选项"),
133	      text,
134	      h("button", {type: "button", class: "link danger", onclick: () => { row.remove(); renumber(); }}, "删除")
135	    );
136	    return row;
137	  }
138	
139	  function addQuestion(type, prefill) {
140	    const isChoice = type === "single_choice";
141	    const options = h("div", {class: "options"});
142	    const card = h("div", {class: "card q-card", "data-type": type},
143	      h("div", {class: "q-head"},
144	        h("span", {class: "q-index"}, "第 N 题"),
145	        h("span", {class: "tag q-type-tag"}, isChoice ? "单选题" : "文本题"),
146	        h("label", {class: "req"},
147	          h("input", {type: "checkbox", class: "q-required"}), "必填（默认非必填）"),
148	        h("span", {class: "spacer"}),
149	        h("button", {type: "button", class: "link danger", onclick: () => { card.remove(); renumber(); }}, "删除本题")
150	      ),
151	      h("textarea", {rows: "1", class: "q-title grow", placeholder: "题目标题（可含换行）"}),
152	      h("p", {class: "field-err q-title-err"})
153	    );
154	    if (isChoice) {
155	      const saved = prefill && Array.isArray(prefill.options) ? prefill.options : null;
156	      if (saved && saved.length) saved.forEach(value => options.append(optionRow(value)));
157	      else options.append(optionRow(), optionRow());
158	      card.append(
159	        options,
160	        h("p", {class: "field-err opt-err"}),
161	        h("button", {type: "button", class: "link add-opt"}, "添加选项")
162	      );
163	      card.querySelector(".add-opt").addEventListener("click", () => {
164	        options.append(optionRow());
165	        renumber();
166	        options.querySelector(".opt-row:last-child .opt-text").focus();
167	      });
168	    }
169	    const qTitleEl = card.querySelector(".q-title");
170	    qTitleEl.addEventListener("input", () => autoGrow(qTitleEl));
171	    if (prefill) {
172	      qTitleEl.value = prefill.title != null ? prefill.title : "";
173	      card.querySelector(".q-required").checked = !!prefill.required;
174	    }
175	    scheduleGrow(qTitleEl);
176	    qBox.append(card);
177	    renumber();
178	    if (!prefill) qTitleEl.focus();
179	    return card;
180	  }
181	
182	  function clearErrors() {
183	    banner.hidden = true;
184	    banner.replaceChildren();
185	    titleErr.textContent = "";
186	    qErr.textContent = "";
187	    qBox.querySelectorAll(".invalid").forEach(el => el.classList.remove("invalid"));
188	    qBox.querySelectorAll(".field-err").forEach(el => { el.textContent = ""; });
189	  }
190	
191	  function showBanner(items) {
192	    banner.replaceChildren(h("strong", null, "问卷未能保存，请修改后重试："), h("ul", null,
193	      items.map(it => h("li", null, h("button", {type: "button", onclick: () => it.el && it.el.focus()}, it.msg)))));
194	    banner.hidden = false;
195	    banner.scrollIntoView({behavior: "smooth", block: "nearest"});
196	  }
197	
198	  const actionButtons = [
199	    h("button", {type: "button", class: "btn secondary", onclick: () => addQuestion("text")}, "添加文本题"),
200	    h("button", {type: "button", class: "btn secondary", onclick: () => addQuestion("single_choice")}, "添加单选题"),
201	    h("span", {class: "spacer"})
